-- 저작권 만료 도서의 태그는 GENRE_TAGS(src/modules/ai/schema.ts)만 쓴다.
-- cover_url 은 비워둔다 — 실제 표지는 알라딘 API image URL 에서 온다 (CLAUDE.md §10).

